// ❌ 느린 기계에서 깨지고, 빠른 기계에선 낭비
await sleep(300);
expect(화면.텍스트()).toBe('저장됨');

// ✅ 조건이 참이 될 때까지 (상한만 둔다)
await expect.poll(() => 화면.텍스트(), { timeout: 5000 }).toBe('저장됨');

const P = {{p}} / 100, N = {{runs}};
let fail = 0;
ctx.clearRect(0, 0, W(), H());
for (let i = 0; i < N; i++) {
  const bad = Math.random() < P;
  if (bad) fail++;
  const x = 16 + (i % 25) * 22, y = 46 + Math.floor(i / 25) * 22;
  ctx.fillStyle = bad ? '#f87171' : '#1f2937';
  ctx.fillRect(x, y, 18, 18);
}
ctx.fillStyle = '#eee'; ctx.font = '14px system-ui';
ctx.fillText('실패 ' + fail + '/' + N + ' — 재현율 ' + ((fail / N) * 100).toFixed(1) + '%', 16, 28);
ctx.fillStyle = '#9ca3af'; ctx.font = '12px system-ui';
ctx.fillText('고쳤다고 말하려면 같은 횟수에서 0 이 나와야 한다', 16, H() - 12);
